"""Writes src/css/static.ts from src/css/static.css (the stylesheet every page gets)."""
import json, pathlib, re

src = pathlib.Path(__file__).parent / 'src' / 'css'
css = (src / 'static.css').read_text()
# Minify: comments, indentation and spaces around punctuation.
css = re.sub(r'/\*.*?\*/', '', css, flags=re.S)
css = re.sub(r'\s+', ' ', css)
css = re.sub(r'\s*([{};,>])\s*', r'\1', css)
css = re.sub(r':\s+', ':', css).replace(';}', '}').strip()
(src / 'static.ts').write_text(
    '// Generated by build-styles.py from static.css.\n'
    f'export const STATIC_CSS = {json.dumps(css)};\n')
print(len(css))
